const N=70;const strands=[];for(let i=0;i<N;i++){strands.push({x:Math.random()*W(),y:Math.random()*H(),a:Math.random()*Math.PI*2,r:1+Math.random()*2.2,sp:0.15+Math.random()*0.35,ph:Math.random()*6.28,len:20+Math.random()*40,hueIdx:Math.floor(Math.random()*PALETTE.length)});}
function hex2rgba(hex,al){const h=hex.replace('#','');const r=parseInt(h.substring(0,2),16);const g=parseInt(h.substring(2,4),16);const b=parseInt(h.substring(4,6),16);return 'rgba('+r+','+g+','+b+','+al+')';}
let t=0;
function frame(){
  t+=0.006;
  ctx.clearRect(0,0,W(),H());
  const w=W(),h=H();
  const cx=w/2, cy=h/2, safe=Math.min(w,h)*0.26;
  for(const s of strands){
    s.ph+=s.sp*0.02;
    const driftX = Math.sin(s.ph+t*2)*18;
    const driftY = Math.cos(s.ph*0.7+t*1.3)*10;
    const px = s.x + driftX;
    const py = (s.y + t*40*s.sp)%( h+60) - 30 + driftY;
    const dx = px-cx, dy=py-cy;
    const dist=Math.sqrt(dx*dx+dy*dy);
    let alpha = 0.55;
    if(dist<safe){ alpha *= Math.max(0, (dist/safe)); }
    const col = PALETTE[s.hueIdx%PALETTE.length];
    ctx.save();
    ctx.translate(px,py);
    ctx.rotate(s.a + Math.sin(t+s.ph)*0.3);
    const grad = ctx.createLinearGradient(-s.len/2,0,s.len/2,0);
    grad.addColorStop(0, hex2rgba(col,0));
    grad.addColorStop(0.5, hex2rgba(col, alpha*0.8));
    grad.addColorStop(1, hex2rgba(col,0));
    ctx.strokeStyle = grad;
    ctx.lineWidth = s.r;
    ctx.lineCap='round';
    ctx.beginPath();
    ctx.moveTo(-s.len/2, Math.sin(t*3+s.ph)*4);
    ctx.quadraticCurveTo(0, Math.cos(t*2+s.ph)*8, s.len/2, Math.sin(t*3+s.ph+1)*4);
    ctx.stroke();
    ctx.restore();
  }
  // soft floating dust particles
  for(let i=0;i<40;i++){
    const ang = t*0.5 + i*0.3;
    const rad = 60 + (i%7)*30 + Math.sin(t*1.5+i)*10;
    const px = cx + Math.cos(ang+i)*rad*2.3;
    const py = cy + Math.sin(ang*1.2+i)*rad*3.1;
    const dist = Math.hypot(px-cx,py-cy);
    if(dist<safe*0.9) continue;
    const col = PALETTE[i%PALETTE.length];
    ctx.beginPath();
    ctx.fillStyle = hex2rgba(col, 0.35);
    ctx.arc(px,py,1.3+Math.sin(t*2+i)*0.6,0,Math.PI*2);
    ctx.fill();
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
